require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';require_once __DIR__.'/../warehouse/_helpers.php';Auth::requireLogin();$db=Database::connect();warehouse_install($db);marketplace_install($db);$pageTitle='Stock Alert Marketplace';$err='';if(is_post()){if(!CSRF::verify())$err='Token keamanan tidak valid.';else try{$qty=(array)($_POST['qty']??[]);$selected=(array)($_POST['selected']??[]);$map=[];foreach($selected as $pid)$map[(int)$pid]=max(0,(int)($qty[$pid]??0));$num=marketplace_v15_create_stock_request($db,$map,'Request Stock dari Stock Alert Marketplace');if(!$num)throw new RuntimeException('Tidak ada item valid / stok gudang tidak tersedia.');flash('success','Request Stock '.$num.' berhasil dibuat.');legacy_redirect('admin/marketplace-stock-alerts/index.php');}catch(Throwable $e){$err=$e->getMessage();}}$rows=marketplace_v15_stock_alerts($db);$ok=flash('success');require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>"><main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Stock Alert & Rekomendasi</h1><p>Produk cabang fulfillment yang menipis dan bisa langsung dibuat Request Stock ke Gudang.</p></div></header><?php if($ok):?><div class="mp-alert success"><?=e($ok)?></div><?php endif;?><?php if($err):?><div class="mp-alert error"><?=e($err)?></div><?php endif;?><section class="mp-panel"><form method="post"><?=CSRF::input()?><div class="table-premium-card"><table class="premium-table"><thead><tr><th></th><th>Produk</th><th>Stok Cabang</th><th>Minimum</th><th>Stok Gudang</th><th>Saran Request</th><th>HPP Gudang</th></tr></thead><tbody><?php foreach($rows as $r):$target=max((int)$r['minimum_stock'],(int)setting('marketplace_stock_alert_threshold','5'))*2;$suggest=max(0,min((int)$r['warehouse_stock'],$target-(int)$r['branch_stock']));?><tr><td><input type="checkbox" name="selected[]" value="<?=$r['id']?>" <?=$suggest>0?'checked':''?>></td><td><b><?=e($r['name'])?></b><br><small><?=e($r['product_code'])?></small></td><td><b><?=e($r['branch_stock'])?></b> <?=e($r['unit'])?></td><td><?=e($r['minimum_stock'])?></td><td><?=e($r['warehouse_stock'])?></td><td><input class="mp-small-input" type="number" min="0" max="<?=$r['warehouse_stock']?>" name="qty[<?=$r['id']?>]" value="<?=$suggest?>"></td><td><?=rupiah($r['unit_cost'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">Semua stok marketplace masih aman.</td></tr><?php endif;?></tbody></table></div><?php if($rows):?><div style="margin-top:16px"><button class="mp-btn"><i class="bi bi-send"></i> Buat Request Stock Terpilih</button></div><?php endif;?></form></section></main><?php require __DIR__.'/../../layouts/admin-footer.php';?>
